CREATE TABLE "Roster60Adventure" ("id" TEXT NOT NULL PRIMARY KEY,"playerId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"revision" INTEGER NOT NULL DEFAULT 0,"activeBattleId" TEXT,"catalogVersion" TEXT NOT NULL,"state" TEXT NOT NULL,"pendingRewards" TEXT NOT NULL,"settlement" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Roster60Adventure_playerId_status_idx" ON "Roster60Adventure"("playerId","status");
CREATE TABLE "Roster60AdventureReceipt" ("playerId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"result" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("playerId","requestId"),FOREIGN KEY("playerId") REFERENCES "Player"("id") ON DELETE CASCADE ON UPDATE CASCADE);
